const path = require("path");
const Database = require(path.join(__dirname, "../wedding-website-production/node_modules/better-sqlite3"));
const fs = require("fs");

const db = new Database(path.join(__dirname, "../wedding-website-production/data/wedding.db"));
const guests = db.prepare("SELECT first_name, last_name, group_id FROM guests ORDER BY id").all();

const lines = [
  "-- Auto-generated by scripts/export-guests.js — do not edit manually.",
  "DELETE FROM guests;",
];

for (const g of guests) {
  const fn = g.first_name.replace(/'/g, "''");
  const ln = g.last_name.replace(/'/g, "''");
  const gid = g.group_id === null ? "NULL" : g.group_id;
  lines.push(`INSERT INTO guests (first_name, last_name, group_id) VALUES ('${fn}', '${ln}', ${gid});`);
}

const outputPath = path.join(__dirname, "../wedding-website-production/data/guests.sql");
fs.writeFileSync(outputPath, lines.join("\n") + "\n");
console.log(`Exported ${guests.length} guest(s) to data/guests.sql`);
